module street_widening(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [15:0] s_in [0:15],\n    input wire [15:0] g_in [0:15],\n    output reg [31:0] total_removed,\n    output reg [15:0] s_out [0:15],\n    output reg done,\n    output reg error\n);\n    \n    // State declarations\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] START_DELAY = 3'd1;\n    localparam [2:0] FORWARD     = 3'd2;\n    localparam [2:0] BACKWARD    = 3'd3;\n    localparam [2:0] VALIDATE    = 3'd4;\n    localparam [2:0] FINISH      = 3'd5;\n    \n    reg [2:0] state, next_state;\n    \n    // Internal registers\n    reg [15:0] s_fwd [0:15];\n    reg [3:0] stored_n;\n    \n    // Counters\n    reg [3:0] i, j;\n    reg [5:0] cycle_counter;\n    \n    // Temporary wires\n    wire [15:0] forward_lower_bound;\n    wire [15:0] forward_upper_bound;\n    wire [15:0] forward_temp;\n    \n    wire [15:0] backward_upper_bound;\n    wire [15:0] backward_temp;\n    wire [15:0] backward_lower_bound;\n    \n    // State machine and control logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            total_removed <= 32'd0;\n            error <= 1'b0;\n            done <= 1'b0;\n            stored_n <= 4'd0;\n            cycle_counter <= 6'd0;\n            \n            // Reset s_fwd array\n            for (i = 0; i < 16; i = i + 1) begin\n                s_fwd[i] <= 16'd0;\n                s_out[i] <= 16'd0;\n            end\n            i <= 4'd0;\n            j <= 4'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    error <= 1'b0;\n                    if (start) begin\n                        stored_n <= n;\n                        state <= START_DELAY;\n                        cycle_counter <= 6'd0;\n                    end\n                end\n                \n                START_DELAY: begin\n                    cycle_counter <= cycle_counter + 6'd1;\n                    state <= FORWARD;\n                    i <= 4'd0;\n                end\n                \n                FORWARD: begin\n                    cycle_counter <= cycle_counter + 6'd1;\n                    \n                    // Compute s_fwd[i]\n                    // First element special case\n                    if (i == 4'd0) begin\n                        s_fwd[0] <= s_in[0];\n                    end else begin\n                        // Compute max(s_in[i], s_fwd[i-1])\n                        forward_lower_bound = (s_in[i] > s_fwd[i-1]) ? s_in[i] : s_fwd[i-1];\n                        forward_upper_bound = s_in[i] + g_in[i];\n                        // Clamp to bounds\n                        forward_temp = (forward_lower_bound < forward_upper_bound) ? forward_lower_bound : forward_upper_bound;\n                        s_fwd[i] <= forward_temp;\n                    end\n                    \n                    if (i == stored_n - 4'd1) begin\n                        state <= BACKWARD;\n                        j <= stored_n - 4'd1;\n                        i <= 4'd0;\n                    end else begin\n                        i <= i + 4'd1;\n                    end\n                end\n                \n                BACKWARD: begin\n                    cycle_counter <= cycle_counter + 6'd1;\n                    \n                    // Compute s_out[j]\n                    if (j == stored_n - 4'd1) begin\n                        // Last element\n                        s_out[j] <= s_fwd[j];\n                    end else begin\n                        backward_upper_bound = (s_fwd[j] < s_out[j+1]) ? s_fwd[j] : s_out[j+1];\n                        backward_temp = (s_in[j] > backward_upper_bound) ? s_in[j] : backward_upper_bound;\n                        s_out[j] <= backward_temp;\n                    end\n                    \n                    if (j == 4'd0) begin\n                        state <= VALIDATE;\n                    end else begin\n                        j <= j - 4'd1;\n                    end\n                end\n                \n                VALIDATE: begin\n                    cycle_counter <= cycle_counter + 6'd1;\n                    total_removed <= 32'd0;\n                    error <= 1'b0;\n                    \n                    // Check constraints and calculate total\n                    for (i = 0; i < 16; i = i + 1) begin\n                        if (i < stored_n) begin\n                            // Check individual constraints\n                            if ((s_out[i] < s_in[i]) || (s_out[i] > s_in[i] + g_in[i]))\n                                error <= 1'b1;\n                            \n                            // Check forwarding constraints\n                            if (i < stored_n - 1)\n                                if (s_out[i] > s_out[i+1])\n                                    error <= 1'b1;\n                            \n                            // Accumulate total removal\n                            total_removed <= total_removed + (s_out[i] - s_in[i]);\n                        end\n                    end\n                    state <= FINISH;\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule